// =========================================================
// HELPER TẠO URL + ROUTE TỪ MENU
// =========================================================

function cleanSegment(value) {
  return String(value == null ? '' : value)
    .trim()
    .replace(/^\/+|\/+$/g, '')
    .replace(/\s+/g, '-')
}

export function getMenuLabel(item) {
  if (!item) return ''
  return item.label || item.text || ''
}

function hasOwnPath(item) {
  return !!item && Object.prototype.hasOwnProperty.call(item, 'path')
}

// URL được lấy từ cây menu.
// Nếu item có `path` thì dùng chính xác path đó, kể cả path = ''.
export function getMenuPath(item, parentPath = '') {
  if (!item) return '/'

  const label = getMenuLabel(item)

  // Home luôn là trang gốc khi không khai báo path riêng.
  if (!parentPath && label === 'Home' && !hasOwnPath(item)) {
    return '/'
  }

  const rawPath = hasOwnPath(item) ? item.path : label
  const segment = cleanSegment(rawPath)
  const parent = String(parentPath || '').replace(/\/+$/g, '')

  // Child path = '' là index route của parent.
  if (!segment) {
    return parent || '/'
  }

  return `${parent}/${segment}` || '/'
}

export function routeNameFromPath(path) {
  if (path === '/') return 'home'

  return String(path || '')
    .replace(/^\/+|\/+$/g, '')
    .replace(/[/:]+/g, '-') || 'route'
}

function relativePath(item) {
  if (hasOwnPath(item)) {
    return cleanSegment(item.path)
  }

  return cleanSegment(getMenuLabel(item))
}

function routeMeta(item) {
  return item && item.meta ? item.meta : undefined
}

// Tạo child routes lồng bên trong một route có component/layout.
function buildNestedChildren(items, parentFullPath) {
  return (items || []).reduce((result, item) => {
    const itemFullPath = getMenuPath(item, parentFullPath)
    const route = {
      path: relativePath(item),
      component: item.component
    }

    if (itemFullPath !== parentFullPath || relativePath(item) === '') {
      route.name = routeNameFromPath(itemFullPath)
    }

    const meta = routeMeta(item)
    if (meta) route.meta = meta

    if (item.alias) route.alias = item.alias

    if (item.children && item.children.length) {
      route.children = buildNestedChildren(item.children, itemFullPath)
    }

    result.push(route)
    return result
  }, [])
}

export function buildRoutes(items, parentPath = '') {
  const routes = []

  ;(items || []).forEach(item => {
    const itemPath = getMenuPath(item, parentPath)
    const hasChildren = !!(item.children && item.children.length)

    // Nếu item có component + children, tạo route lồng thật sự.
    // Ví dụ MonHoc dùng MainLayoutSub.vue rồi render children bằng <router-view />.
    if (item.component && hasChildren) {
      const route = {
        path: itemPath,
        component: item.component,
        children: buildNestedChildren(item.children, itemPath)
      }

      const meta = routeMeta(item)
      if (meta) route.meta = meta
      if (item.alias) route.alias = item.alias

      routes.push(route)
      return
    }

    if (item.component) {
      const route = {
        path: itemPath,
        name: routeNameFromPath(itemPath),
        component: item.component
      }

      const meta = routeMeta(item)
      if (meta) route.meta = meta
      if (item.alias) route.alias = item.alias

      routes.push(route)
    }

    // Nhóm menu không có component (Generator, Generator2...) vẫn sinh route con độc lập.
    if (hasChildren) {
      routes.push(...buildRoutes(item.children, itemPath))
    }
  })

  return routes
}
